/* PaKuWord – polska paczka dzienna 2026-11-25: nowa dziedzina Kuchnia i gotowanie (30) + 30 haseł w istniejących dziedzinach */
window.PW_CONTENT = window.PW_CONTENT || {};
window.PW_CONTENT.pl = (window.PW_CONTENT.pl || []).concat([
/* ---------- KUCHNIA I GOTOWANIE ---------- */
{id:"cook_mise_en_place",cat:"cook",t:"Mise en place",
 s:"Przygotowanie wszystkich składników i narzędzi, zanim zacznie się gotować.",
 l:"Mise en place to przygotowanie wszystkiego, zanim włączymy palnik: umyte i pokrojone warzywa, odmierzone przyprawy, otwarte puszki, wyjęte garnki i łyżki. Zawodowi kucharze tak urządzają swoje stanowisko, żeby w ruchliwej porze niczego nie szukać. W domu dzięki temu gotuje się spokojniej i bezpieczniej, bo nic się nie przypala, gdy szukamy czosnku. Chodzi nie tyle o porządek dla porządku, ile o przemyślenie przepisu od początku do końca.",
 x:"Przeczytała przepis dwa razy i zrobiła mise en place, więc danie z woka było gotowe w dziesięć minut.",
 f:"Wyrażenie jest francuskie i dosłownie znaczy ustawienie na miejscu; kucharze używają go także w przenośni, mówiąc o każdym starannym przygotowaniu.",
 js:"Przygotowanie wszystkiego, zanim zaczniesz gotować.",
 jl:"Dobrzy kucharze najpierw kładą na blacie wszystko, czego potrzebują: umyte i odmierzone składniki, miski, łyżki i garnki. Potem nie muszą biegać po kuchni, kiedy coś już bulgocze na kuchence.",
 jx:"Zanim upiekliśmy z tatą ciasteczka, Leon położył na stole mąkę, masło, cukier i miskę."},
{id:"cook_umami",cat:"cook",t:"Umami",
 s:"Głęboki, wytrawny, „pełny” smak, nazywany często piątym smakiem podstawowym.",
 l:"Oprócz słodkiego, kwaśnego, słonego i gorzkiego nasz język wyczuwa umami, czyli bogaty, wytrawny smak. Odpowiadają za niego głównie glutaminiany i kilka pokrewnych związków obecnych w parmezanie, pomidorach, grzybach, sosie sojowym, rosole czy wodorostach. Dojrzewanie, suszenie i fermentacja często go wzmacniają, dlatego dojrzały ser i suszone grzyby smakują tak intensywnie. Umami to nie to samo co słony smak: sprawia raczej, że jedzenie wydaje się sycące i pełne.",
 x:"Łyżka pasty miso dodała zupie warzywnej przyjemnej głębi umami.",
 f:"Japoński chemik Kikunae Ikeda w 1908 roku wykazał, że za ten smak odpowiada glutaminian, badając wywar z wodorostów kombu.",
 js:"Bogaty, wytrawny smak, jak w serze, pomidorach albo rosole.",
 jl:"Język czuje smak słodki, kwaśny, słony i gorzki. Naukowcy odkryli też piąty smak – umami. To ten pyszny, „pełny” smak, który czujesz w sosie pomidorowym, serze, grzybach i rosole.",
 jx:"Babcina zupa grzybowa jest pełna smaku umami."},
{id:"cook_maillard",cat:"cook",t:"Reakcja Maillarda",
 s:"Reakcja białek z cukrami, która podczas smażenia, pieczenia i opiekania nadaje potrawom brązowy kolor i aromat.",
 l:"Gdy jedzenie zawierające białka i cukry ogrzewa się znacznie powyżej temperatury wrzenia wody, związki te reagują ze sobą i powstają setki nowych substancji smakowych i zapachowych oraz brązowa barwa. To reakcja Maillarda: dzięki niej mamy skórkę chleba, smak tostów, palonej kawy i przyrumienionego mięsa. Potrzebuje suchej, gorącej powierzchni, dlatego mokre i stłoczone na patelni kawałki raczej się duszą, niż rumienią. To co innego niż karmelizacja, w której bierze udział sam cukier.",
 x:"Osusz pieczarki przed smażeniem, inaczej reakcja Maillarda nie zdąży ich zrumienić.",
 f:"Nazwa pochodzi od francuskiego chemika Louisa-Camille’a Maillarda, który opisał tę reakcję w 1912 roku.",
 js:"Zmiana, dzięki której tost i pieczone ziemniaki robią się złote i smaczne.",
 jl:"Kiedy chleb zamienia się w tost, robi się brązowy i pięknie pachnie. Dzieje się tak, bo w gorącu maleńkie cząstki jedzenia łączą się i powstają nowe smaki i zapachy. Naukowcy nazywają to reakcją Maillarda.",
 jx:"Złota skórka na naszej pizzy to właśnie reakcja Maillarda."},
{id:"cook_caramelisation",cat:"cook",t:"Karmelizacja",
 s:"Brązowienie cukru pod wpływem wysokiej temperatury, dające słodko-orzechowy, lekko gorzkawy smak.",
 l:"Mocno ogrzany cukier, mniej więcej od stu sześćdziesięciu stopni Celsjusza, topi się, złocieje, a potem brązowieje i nabiera złożonego smaku. Tak powstaje karmel do sosów, krówek czy chrupiącej warstwy na crème brûlée. Mówi się też o karmelizowaniu cebuli duszonej powoli na złoto, choć tam działa również reakcja Maillarda, bo cebula zawiera białka. Karmel w kilka chwil przechodzi od idealnego do spalonego, więc trzeba go pilnować, a gorący cukier powoduje groźne oparzenia.",
 x:"Dusił cebulę przez czterdzieści minut, aż się skarmelizowała i zrobiła słodka.",
 f:"Słowo karmel trafiło do polszczyzny z francuskiego, a Francuzi przejęli je z hiszpańskiego caramelo.",
 js:"Kiedy cukier bardzo się nagrzewa i zamienia w złoty, lepki karmel.",
 jl:"Jeśli cukier mocno się podgrzeje, topi się i robi się złotobrązowy. To karmel. Jest bardzo, bardzo gorący, więc robią go tylko dorośli, ale smakuje świetnie na deserach.",
 jx:"Mama robiła karmel do naleśników, a ja patrzyłam z bezpiecznej odległości."},
{id:"cook_emulsion",cat:"cook",t:"Emulsja",
 s:"Mieszanina dwóch cieczy, które same się nie łączą, na przykład oleju i wody, w której drobne kropelki jednej są rozproszone w drugiej.",
 l:"Olej i woda same się rozdzielają, ale gdy mocno je ubijemy, jedna ciecz rozpada się na maleńkie kropelki w drugiej. Żeby się z powrotem nie rozwarstwiły, potrzebny jest emulgator, czyli substancja, która trzyma kropelki osobno. W majonezie jest nim lecytyna z żółtka, w winegrecie na chwilę pomaga musztarda. Gdy emulsja się rozwarstwi, kucharze mówią, że się zważyła. Na emulsjach opiera się wiele sosów, dressingów, a nawet lody.",
 x:"Dodawaj olej kropla po kropli, bo inaczej emulsja się zwarzy i majonez będzie rzadki.",
 f:"Mleko to naturalna emulsja: maleńkie kropelki tłuszczu zawieszone w wodnistym płynie.",
 js:"Mieszanka oleju i wody, która się nie rozdziela, jak majonez.",
 jl:"Zwykle olej pływa na wodzie. Ale jeśli bardzo mocno je wymieszasz z żółtkiem albo musztardą, zostają razem jako gładka masa. Taka mieszanka nazywa się emulsją.",
 jx:"Potrząsaliśmy w słoiku olejem, sokiem z cytryny i musztardą i wyszedł nam sos do sałatki."},
{id:"cook_roux",cat:"cook",t:"Zasmażka (roux)",
 s:"Mąka podsmażona na tłuszczu, używana do zagęszczania sosów i zup.",
 l:"Zasmażkę robi się, rozpuszczając masło lub inny tłuszcz, dodając tyle samo mąki i smażąc chwilę, cały czas mieszając. Potem powoli wlewa się płyn, na przykład mleko albo wywar, i mąka zagęszcza go bez grudek. Jasna zasmażka, smażona krótko, jest podstawą sosu beszamelowego; dłużej smażona, ciemniejsza ma orzechowy smak, ale słabiej zagęszcza. Smażenie usuwa też surowy, mączny posmak. W kuchni francuskiej nazywa się ją roux.",
 x:"Sos serowy zacznij od zasmażki z masła i mąki, a potem stopniowo dolewaj mleko.",
 f:"W dawnej kuchni polskiej zasmażką często zagęszczano zupy i sosy; dziś częściej używa się do tego mąki rozmieszanej ze śmietaną.",
 js:"Masło i mąka podsmażone razem, żeby zagęścić sos.",
 jl:"Żeby sos był gęsty i gładki, kucharze roztapiają masło, dodają mąkę i chwilę ją podsmażają. Potem powoli wlewają mleko i mieszają. Sos gęstnieje, tak jak ten do lasagne.",
 jx:"Mieszałem zasmażkę, a mama wlewała mleko do sosu."},
{id:"cook_blanching",cat:"cook",t:"Blanszowanie",
 s:"Bardzo krótkie gotowanie we wrzątku, a potem szybkie schłodzenie, najczęściej w lodowatej wodzie.",
 l:"Blanszując warzywa, wrzuca się je na chwilę do wrzątku, zwykle na minutę do trzech, a potem od razu do bardzo zimnej wody, żeby przerwać gotowanie. Zielone warzywa zachowują wtedy żywy kolor i lekką chrupkość, a pomidory czy brzoskwinie łatwo obrać ze skórki. Przed mrożeniem blanszowanie spowalnia naturalne enzymy, które w zamrażarce psułyby kolor, smak i konsystencję. To krótkie, częściowe gotowanie, a nie pełne. Po polsku mówi się też obgotowanie albo sparzanie.",
 x:"Zblanszuj fasolkę szparagową, żeby w sałatce została zielona.",
 f:"Słowo pochodzi od francuskiego blanchir, czyli wybielać, bo dawniej w ten sposób bielono na przykład migdały.",
 js:"Bardzo krótkie gotowanie we wrzątku i szybkie chłodzenie w zimnej wodzie.",
 jl:"Czasem kucharze wkładają warzywa do wrzątku tylko na minutę lub dwie, a potem prosto do lodowatej wody. Warzywa zostają jaskrawozielone i trochę chrupiące. Wrzątkiem zajmuje się dorosły.",
 jx:"Tata zblanszował brokuły i były zielone jak kredka."},
{id:"cook_braising",cat:"cook",t:"Duszenie",
 s:"Powolne gotowanie w przykrytym naczyniu z niewielką ilością płynu, zwykle po wcześniejszym obsmażeniu.",
 l:"Duszenie zaczyna się często od obsmażenia mięsa lub warzyw na gorącym tłuszczu. Potem dodaje się trochę płynu, na przykład wywaru, wina albo wody, przykrywa naczynie i gotuje łagodnie przez długi czas na kuchence lub w piekarniku. Powolne, wilgotne ciepło rozkłada twardą tkankę łączną, dzięki czemu tańsze, twardsze kawałki mięsa robią się miękkie. Tak przyrządza się na przykład gulasz, zrazy czy duszoną kapustę.",
 x:"Wołowina dusiła się trzy godziny, aż rozpadała się pod widelcem.",
 f:"Gulasz przyszedł do nas z Węgier, gdzie słowo gulyás oznacza pasterza bydła, który przyrządzał taką potrawę w kotle.",
 js:"Powolne gotowanie w garnku z pokrywką i odrobiną płynu.",
 jl:"Duszenie to powolny sposób gotowania. Jedzenie leży w garnku pod pokrywką z odrobiną płynu i długo, spokojnie się gotuje. Na końcu jest bardzo miękkie i pełne smaku.",
 jx:"Duszona marchewka była tak miękka, że młodsza siostra rozgniatała ją łyżeczką."},
{id:"cook_simmer",cat:"cook",t:"Gotowanie na wolnym ogniu",
 s:"Łagodne gotowanie tuż poniżej wrzenia, gdy na powierzchni pojawiają się tylko pojedyncze bąbelki.",
 l:"Gotując na wolnym ogniu, utrzymujemy płyn tuż poniżej pełnego wrzenia: na powierzchni powoli pojawiają się i pękają małe bąbelki zamiast dużych, burzliwych. Tak gotuje się zupy, wywary, sosy i gulasze, bo potrawa gotuje się równo, nie rozpada się i nie przywiera. Mocne wrzenie może zmętnić rosół i sprawić, że mięso stwardnieje. Przepisy często każą najpierw zagotować, a potem zmniejszyć ogień. Polscy kucharze mówią obrazowo, że rosół ma tylko mrugać.",
 x:"Gotuj zupę na wolnym ogniu przez dwadzieścia minut pod uchyloną pokrywką.",
 f:"Wysoko w górach woda wrze w niższej temperaturze, więc potrawy gotują się tam dłużej.",
 js:"Gotowanie bardzo spokojne, z małymi, powolnymi bąbelkami.",
 jl:"Kiedy zupa gotuje się na wolnym ogniu, widać tylko małe bąbelki, które powoli pękają, a nie duże, skaczące. Takie łagodne gotowanie sprawia, że zupa nie pryska i się nie przypala.",
 jx:"Rosół cichutko mrugał w garnku, a my nakrywaliśmy do stołu."},
{id:"cook_al_dente",cat:"cook",t:"Al dente",
 s:"Ugotowany tak, by makaron lub warzywa były miękkie, ale wciąż lekko twarde przy gryzieniu.",
 l:"Al dente to makaron, ryż albo warzywa ugotowane na wskroś, ale z lekkim oporem w środku. Włosi wolą tak przygotowany makaron, bo przyjemnie się go gryzie i lepiej trzyma sos, a rozgotowany robi się miękki i lepki. Najprostszy sprawdzian to wyjąć kawałek i ugryźć minutę lub dwie przed czasem podanym na opakowaniu. Makaron często dochodzi jeszcze chwilę w sosie, więc wyjęty al dente nie rozgotuje się.",
 x:"Odcedź spaghetti, kiedy jest jeszcze al dente, i od razu wrzuć je do sosu.",
 f:"Po włosku wyrażenie znaczy na ząb, czyli tak, by czuć lekki opór przy gryzieniu.",
 js:"Makaron ugotowany, ale jeszcze troszkę twardy.",
 jl:"Al dente to po włosku na ząb. Tak wiele osób lubi makaron: jest miękki, ale nie rozlazły i nie papkowaty. Można to sprawdzić, próbując jedną nitkę.",
 jx:"Spróbowałam jednego świderka i zawołałam: jest al dente, gotowe!"},
{id:"cook_deglazing",cat:"cook",t:"Deglasowanie",
 s:"Wlanie płynu na gorącą patelnię, żeby rozpuścić przywarte, zrumienione resztki i zrobić z nich sos.",
 l:"Po smażeniu mięsa lub warzyw na dnie patelni zostaje warstwa brązowych, przywartych resztek. Są pełne smaku powstałego w reakcji Maillarda. Deglasując, wlewamy na gorącą patelnię trochę płynu, na przykład wywaru, wina, wody albo soku, i zeskrobujemy dno drewnianą łyżką, aż resztki się rozpuszczą. To początek smacznego sosu z patelni. Przy okazji patelnię łatwiej potem umyć.",
 x:"Po usmażeniu kurczaka zdeglasowała patelnię odrobiną bulionu i zrobiła sos.",
 f:"Kucharze nazywają tę brązową warstwę na patelni z francuska fond, czyli podstawa albo dno.",
 js:"Wlewanie odrobiny płynu na gorącą patelnię, żeby zebrać smaczne brązowe resztki.",
 jl:"Po smażeniu na patelni zostają przywarte, brązowe kawałeczki. Są bardzo smaczne! Kucharz wlewa trochę płynu i zeskrobuje je łyżką. Wychodzi z tego pyszny sos.",
 jx:"Tata zdeglasował patelnię i sos był jeszcze lepszy niż ostatnio."},
{id:"cook_reduction",cat:"cook",t:"Redukcja",
 s:"Gotowanie płynu bez przykrycia, by część wody odparowała, a sos zgęstniał i nabrał mocniejszego smaku.",
 l:"Redukując sos, gotujemy go bez pokrywki, tak by woda zamieniała się w parę i uciekała, a zostawało mniej gęstszego, bardziej skoncentrowanego płynu. Redukuje się wywary, wino, soki owocowe i ocet, by uzyskać lśniące sosy i glazury. Sól nie odparowuje, więc sos, który na początku był dobrze doprawiony, po redukcji może być za słony; lepiej doprawiać go na końcu. W szerokim naczyniu redukcja idzie szybciej, bo powierzchnia parowania jest większa.",
 x:"Redukcja z octu balsamicznego była słodka i gęsta, idealna do truskawek.",
 f:"Niektóre klasyczne sosy francuskie powstają przez redukcję wywaru do niewielkiej części pierwotnej ilości, aż po ostygnięciu stężeje niemal w galaretę.",
 js:"Gotowanie sosu dłużej, aż część wody zniknie i sos zgęstnieje.",
 jl:"Kiedy sos gotuje się bez pokrywki, część wody zamienia się w parę i ucieka. Zostaje gęstszy i smaczniejszy sos. Kucharze nazywają to redukcją.",
 jx:"Gotowaliśmy sos z jagód, aż był na tyle gęsty, żeby polać nim lody."},
{id:"cook_stock",cat:"cook",t:"Wywar (bulion)",
 s:"Aromatyczny płyn powstały z długiego gotowania kości, mięsa lub warzyw, baza zup i sosów.",
 l:"Wywar powstaje, gdy kości, mięso, warzywa, zioła i przyprawy długo gotują się na wolnym ogniu w wodzie, a potem płyn się przecedza. Nadaje smak i treść zupom, risotto, sosom i potrawom duszonym. Wywar z kości zawiera żelatynę, przez co po wystudzeniu może tężeć. Wywar warzywny gotuje się krócej i pasuje do dań wegetariańskich. Najbardziej znany polski wywar, podawany jako osobna zupa, to rosół.",
 x:"Obierki warzyw trzyma w zamrażarce, żeby w niedzielę ugotować z nich wywar.",
 f:"W wielu polskich domach rosół z makaronem to tradycyjna niedzielna zupa.",
 js:"Smaczny płyn z długo gotowanych warzyw albo kości.",
 jl:"Kucharze wkładają do dużego garnka warzywa, zioła i czasem kości i długo gotują. Potem przelewają wszystko przez sitko. Ten smaczny płyn to wywar. Z niego robi się zupy i sosy.",
 jx:"Nasza zupa jest ugotowana na domowym wywarze warzywnym."},
{id:"cook_marinade",cat:"cook",t:"Marynata",
 s:"Przyprawiony płyn, w którym moczy się jedzenie przed gotowaniem albo w którym się je konserwuje.",
 l:"Marynata do mięsa łączy zwykle coś kwaśnego, jak sok z cytryny, ocet albo jogurt, z olejem, ziołami, przyprawami, czosnkiem czy sosem sojowym. Mięso, ryby, tofu lub warzywa leżą w niej od kilku minut do doby, w lodówce. Smak wnika głównie w powierzchnię, a mocny kwas trzymany zbyt długo może rozmiękczyć rybę. Marynatę po surowym mięsie trzeba zagotować, zanim użyje się jej jako sosu. W polskiej kuchni marynatą nazywa się też zalewę octową do grzybków czy ogórków konserwowych.",
 x:"Kurczak spędził noc w marynacie z jogurtu i przypraw, zanim trafił na grill.",
 f:"Słowo pochodzi od hiszpańskiego marinar, czyli zaprawiać w solance, związanego ze słowem mar, morze.",
 js:"Smaczny sos, w którym jedzenie moczy się przed gotowaniem.",
 jl:"Przed gotowaniem ludzie czasem zostawiają jedzenie w mieszance soku, oleju i przypraw. Leży w lodówce i nasiąka smakiem. Taka mieszanka to marynata.",
 jx:"Włożyliśmy tofu do marynaty z miodem i sosem sojowym, a potem upiekliśmy."},
{id:"cook_fermentation",cat:"cook",t:"Fermentacja",
 s:"Proces, w którym drobnoustroje, takie jak bakterie czy drożdże, przemieniają jedzenie, często czyniąc je kwaśnym, musującym lub trwalszym.",
 l:"Podczas fermentacji drobnoustroje żywią się cukrami w jedzeniu i zamieniają je w kwasy, gazy albo alkohol. Bakterie zmieniają mleko w jogurt i kefir, a kapustę i ogórki w kiszonki, drożdże zaś sprawiają, że rośnie chleb. Przez tysiące lat fermentacja pozwalała przechować jedzenie bez lodówki i nadawała mu kwaśny, wyrazisty smak. Domowe kiszenie wymaga czystych naczyń i odpowiedniej ilości soli, bo w złych warunkach mogą się rozwinąć niepożądane drobnoustroje.",
 x:"Kiszona kapusta powstaje dzięki fermentacji: wystarczy kapusta, sól i czas.",
 f:"W latach pięćdziesiątych i sześćdziesiątych dziewiętnastego wieku Ludwik Pasteur wykazał, że fermentację wywołują żywe drobnoustroje.",
 js:"Kiedy maleńkie żyjątka zmieniają jedzenie, na przykład mleko w jogurt.",
 jl:"Istnieją maleńkie żyjątka, za małe, żeby je zobaczyć – bakterie i drożdże. Niektóre są bardzo pomocne! Zmieniają mleko w jogurt, ogórki w kiszone, a ciasto na chleb sprawiają, że rośnie. Ta przemiana to fermentacja.",
 jx:"W klasie nastawiliśmy w słoiku ogórki i patrzyliśmy, jak fermentują."},
{id:"cook_gluten",cat:"cook",t:"Gluten",
 s:"Białka pszenicy, jęczmienia i żyta, dzięki którym ciasto jest elastyczne.",
 l:"Gdy mąkę z pszenicy, jęczmienia lub żyta połączymy z wodą i wyrabiamy, jej białka tworzą rozciągliwą sieć nazywaną glutenem. Sieć ta zatrzymuje gaz, dlatego chleb może wyrosnąć i być sprężysty. Do chleba piekarze wybierają mąkę z dużą ilością białka, a do ciast biszkoptowych delikatniejszą, żeby były miękkie. Niektóre osoby muszą unikać glutenu ze względów zdrowotnych, na przykład chorzy na celiakię, dlatego etykiety wyraźnie go oznaczają.",
 x:"Wyrabianie ciasta rozwija gluten i sprawia, że chleb jest sprężysty.",
 f:"Słowo gluten pochodzi z łaciny i znaczy klej.",
 js:"Coś w mące, co sprawia, że ciasto jest rozciągliwe.",
 jl:"Kiedy zmieszasz mąkę z wodą i długo ugniatasz, ciasto robi się rozciągliwe jak gumka. To dzięki glutenowi. Niektórym osobom gluten szkodzi, więc jedzą specjalne produkty bezglutenowe.",
 jx:"Kiedy rozciągałam ciasto na pizzę, nie rwało się dzięki glutenowi."},
{id:"cook_proving",cat:"cook",t:"Wyrastanie ciasta",
 s:"Odstawienie ciasta drożdżowego, żeby przed pieczeniem urosło.",
 l:"Po wyrobieniu ciasto drożdżowe odstawia się w ciepłe miejsce, zwykle przykryte ściereczką, żeby drożdże mogły żywić się cukrami i wytwarzać dwutlenek węgla. Gaz zostaje uwięziony w sieci glutenu i ciasto rośnie. Wiele wypieków wyrasta dwa razy: raz w misce i drugi raz po uformowaniu. Za krótko wyrośnięte da zbity chleb, zbyt długo – może opaść w piekarniku. Prosty test: lekko naciśnięte ciasto powinno powoli wracać do kształtu. Piekarze mówią też, że ciasto garuje.",
 x:"Bułeczki muszą rosnąć jeszcze pół godziny, zanim trafią do piekarnika.",
 f:"Drożdże to żywe, jednokomórkowe grzyby; zbyt gorący płyn może je zabić, dlatego mleko do ciasta drożdżowego powinno być tylko letnie.",
 js:"Czekanie, aż ciasto drożdżowe urośnie.",
 jl:"Ciasto z drożdżami musi odpocząć w ciepłym miejscu. Wtedy drożdże robią w nim maleńkie bąbelki gazu i ciasto powoli robi się coraz większe. To wyrastanie ciasta.",
 jx:"Przykryliśmy ciasto ściereczką i czekaliśmy, aż wyrośnie."},
{id:"cook_raising_agent",cat:"cook",t:"Soda oczyszczona i proszek do pieczenia",
 s:"Dwa środki spulchniające, które wydzielają pęcherzyki gazu i sprawiają, że ciasta są puszyste.",
 l:"Soda oczyszczona to wodorowęglan sodu. Wydziela dwutlenek węgla, gdy zetknie się z kwasem, na przykład z jogurtem, maślanką, sokiem z cytryny albo kakao. Proszek do pieczenia zawiera już sodę razem z suchym kwasem, więc wystarczy mu wilgoć i ciepło. Dlatego przepisy z kwaśnymi składnikami często używają sody, a inne proszku. Za dużo któregokolwiek z nich daje mydlany lub gorzki posmak.",
 x:"Babeczki wyszły płaskie, bo zapomniałam o proszku do pieczenia.",
 f:"Gotowy proszek do pieczenia w małych torebkach upowszechnił się pod koniec dziewiętnastego wieku, między innymi dzięki niemieckiemu aptekarzowi Augustowi Oetkerowi.",
 js:"Białe proszki, dzięki którym ciasto rośnie i jest puszyste.",
 jl:"Ciasto jest lekkie dzięki maleńkim bąbelkom w środku. Proszek do pieczenia i soda pomagają je zrobić, kiedy zrobią się mokre i ciepłe. Bez nich wiele ciast byłoby płaskich jak naleśniki.",
 jx:"Odmierzyłem łyżeczkę proszku do pieczenia do chlebka bananowego."},
{id:"cook_bain_marie",cat:"cook",t:"Kąpiel wodna (bain-marie)",
 s:"Podgrzewanie potrawy w misce lub naczyniu ustawionym nad gorącą wodą albo w niej, by grzała się łagodnie i równo.",
 l:"Kąpiel wodna chroni delikatne potrawy przed bezpośrednim ogniem. Do roztapiania czekolady stawia się żaroodporną miskę nad garnkiem z lekko gotującą się wodą, tak by jej nie dotykała. Sernik czy budyń jajeczny piecze się z kolei w naczyniu wstawionym do blachy z gorącą wodą. Woda nie nagrzewa się powyżej temperatury wrzenia, więc potrawa ogrzewa się powoli i równo i rzadziej się przypala, zwarza albo pęka.",
 x:"Rozpuść czekoladę w kąpieli wodnej, żeby się nie przypaliła.",
 f:"Francuska nazwa bain-marie znaczy kąpiel Marii i bywa łączona z Marią Żydówką, dawną alchemiczką, choć ta opowieść jest stara i niepewna.",
 js:"Miska z jedzeniem ustawiona nad ciepłą wodą, żeby powoli się podgrzało.",
 jl:"Czekolada łatwo się przypala w garnku. Dlatego kucharze wkładają ją do miski nad garnkiem z gorącą wodą. Para powoli ogrzewa miskę, a czekolada topi się gładka i błyszcząca.",
 jx:"Roztopiliśmy czekoladę w kąpieli wodnej i maczaliśmy w niej truskawki."},
{id:"cook_tempering",cat:"cook",t:"Temperowanie czekolady",
 s:"Roztapianie, schładzanie i delikatne ponowne podgrzewanie czekolady, by zastygła błyszcząca i łamała się z trzaskiem.",
 l:"Masło kakaowe w czekoladzie może krzepnąć w kilku różnych strukturach kryształów. Jeśli roztopiona czekolada po prostu ostygnie, często robi się matowa, miękka i w smugi. Temperowanie polega na starannym prowadzeniu temperatury: podgrzaniu, schłodzeniu i lekkim ponownym ogrzaniu, tak by powstały tylko trwałe kryształy. Temperowana czekolada błyszczy, łamie się z trzaskiem i nie topi się od razu w palcach. Czekoladnicy używają jej do tabliczek, pralin i dekoracji.",
 x:"Czekoladowe ozdoby były matowe, bo nie wytemperowała czekolady.",
 f:"Masło kakaowe może tworzyć sześć różnych form kryształów, a tylko jedna z nich daje połysk i chrupiący trzask.",
 js:"Roztapianie i chłodzenie czekolady w specjalny sposób, żeby błyszczała.",
 jl:"Czekoladnicy ogrzewają czekoladę, schładzają ją i znów odrobinę ogrzewają, bardzo ostrożnie. Dzięki temu czekolada błyszczy i trzaska, kiedy się ją łamie. To temperowanie.",
 jx:"Tabliczka zrobiła trzask, bo czekolada była dobrze wytemperowana."},
{id:"cook_julienne",cat:"cook",t:"Julienne (krojenie w słupki)",
 s:"Krojenie warzyw w długie, cienkie paseczki przypominające zapałki.",
 l:"Żeby pokroić marchewkę w julienne, tnie się ją na cienkie plasterki, układa je w stos i kroi w równe, cienkie słupki. Jednakowe kawałki gotują się w tym samym czasie i ładnie wyglądają w daniach z woka, surówkach i jako dekoracja. Inne klasyczne cięcia to brunoise, czyli drobniutka kostka z pociętych słupków, i chiffonade, cienkie wstążki liści ziół. Bezpieczne krojenie wymaga podwinięcia opuszków palców, z dala od ostrza.",
 x:"Pokrój paprykę i marchewkę w julienne do sajgonek.",
 f:"Słupki można szybko kroić na mandolinie, ale jest tak ostra, że kucharze często zakładają rękawice odporne na przecięcia.",
 js:"Krojenie jedzenia w cienkie słupki jak zapałki.",
 jl:"Julienne to elegancka nazwa krojenia warzyw w długie, cienkie słupki. Ładnie wyglądają w sałatkach. Noże są ostre, więc dzieci próbują tylko z dorosłym i bezpiecznym nożykiem.",
 jx:"Marchewka w moim pudełku na drugie śniadanie była pokrojona w julienne."},
{id:"cook_smoke_point",cat:"cook",t:"Punkt dymienia",
 s:"Temperatura, w której olej lub tłuszcz zaczyna dymić.",
 l:"Każdy olej i tłuszcz zaczyna dymić po przekroczeniu określonej temperatury, nazywanej punktem dymienia. Powyżej niej tłuszcz się rozkłada, gorzknieje i wydziela drażniący dym, a dalej podgrzewany może się zapalić. Oleje rafinowane mają zwykle wyższy punkt dymienia niż nierafinowane, a masło dymi szybciej niż większość olejów przez zawarte w nim białka mleka. Płonącego oleju nigdy nie gasi się wodą: trzeba wyłączyć palnik i przykryć naczynie pokrywką albo kocem gaśniczym.",
 x:"Do smażenia wybrała olej o wysokim punkcie dymienia, a tłoczony na zimno zostawiła do sałatki.",
 f:"Masło klarowane, z którego usunięto białka mleka, można podgrzać znacznie mocniej niż zwykłe, zanim zacznie dymić.",
 js:"Temperatura, w której olej jest tak gorący, że zaczyna dymić.",
 jl:"Jeśli olej na patelni za bardzo się nagrzeje, zaczyna dymić. To znak, że jest za gorący i może być niebezpieczny. Gorącym olejem zajmują się tylko dorośli. Płonącego oleju nigdy nie gasi się wodą – dorosły przykrywa patelnię pokrywką.",
 jx:"Olej zaczął dymić, więc tata od razu zmniejszył ogień."},
{id:"cook_cross_contamination",cat:"cook",t:"Zanieczyszczenie krzyżowe",
 s:"Przenoszenie szkodliwych drobnoustrojów z jednego produktu, powierzchni lub narzędzia na inne.",
 l:"Surowe mięso, drób, ryby i jajka mogą zawierać bakterie wywołujące zatrucia pokarmowe. Jeśli ten sam nóż, deska albo ręce dotkną surowego kurczaka, a potem sałaty, bakterie mogą przejść na jedzenie, którego już nie będziemy gotować. Żeby temu zapobiec, trzyma się surowe produkty z dala od gotowych do jedzenia, używa osobnych desek, myje ręce mydłem i czyści blaty. Surowe mięso najlepiej przechowywać na najniższej półce lodówki, by jego sok nie kapał na inne produkty.",
 x:"Żeby uniknąć zanieczyszczenia krzyżowego, kroimy mięso i warzywa na osobnych deskach.",
 f:"W wielu profesjonalnych kuchniach deski są oznaczone kolorami, na przykład czerwona do surowego mięsa, a zielona do warzyw i owoców.",
 js:"Kiedy zarazki z surowego jedzenia przechodzą na inne jedzenie.",
 jl:"Na surowym mięsie i surowych jajkach mogą być zarazki. Jeśli dotkniesz surowego mięsa, a potem kanapki bez mycia rąk, zarazki mogą przejść na kanapkę. Dlatego myjemy ręce i używamy różnych desek.",
 jx:"Po dotknięciu surowych jajek Zosia umyła ręce, zanim kroiła owoce."},
{id:"cook_sous_vide",cat:"cook",t:"Sous-vide (gotowanie próżniowe)",
 s:"Gotowanie jedzenia zamkniętego w woreczku w kąpieli wodnej o dokładnej, stałej temperaturze.",
 l:"W metodzie sous-vide jedzenie zamyka się szczelnie w woreczku, zwykle po odessaniu powietrza, i zanurza w wodzie podgrzewanej przez urządzenie, które utrzymuje dokładną temperaturę. Woda nigdy nie jest cieplejsza niż zadana temperatura, więc mięso czy ryba gotują się równo od brzegu do środka i bardzo trudno je przegotować. Na koniec zwykle krótko się je obsmaża na gorącej patelni dla koloru i smaku. Dla bezpieczeństwa trzeba przestrzegać właściwych temperatur i czasów.",
 x:"Restauracja gotuje łososia metodą sous-vide, a potem przypieka skórkę na patelni.",
 f:"Nazwa po francusku znaczy pod próżnią, a metodę rozwinięto we francuskich restauracjach w latach siedemdziesiątych dwudziestego wieku.",
 js:"Gotowanie jedzenia w zamkniętym woreczku w ciepłej wodzie.",
 jl:"Niektórzy kucharze wkładają jedzenie do zamkniętego woreczka, a woreczek do ciepłej wody. Specjalne urządzenie pilnuje, żeby woda była cały czas tak samo ciepła. Jedzenie gotuje się powoli i równo.",
 jx:"Wujek ugotował jajka metodą sous-vide i były idealnie miękkie."},
{id:"cook_seasoning",cat:"cook",t:"Doprawianie (do smaku)",
 s:"Dodawanie soli, pieprzu, ziół, przypraw lub czegoś kwaśnego, by wydobyć i zrównoważyć smak potrawy.",
 l:"Doprawianie to dopasowywanie smaku potrawy, najczęściej solą i pieprzem, ale też ziołami, przyprawami, sokiem z cytryny czy octem. Gdy przepis mówi dopraw do smaku, prosi, żebyśmy spróbowali i sami zdecydowali, bo składniki i gusta są różne. Odrobina soli sprawia, że jedzenie bardziej smakuje sobą, a kilka kropel kwasu ożywia mdłą potrawę. Łatwiej dodać, niż odjąć, więc kucharze doprawiają po trochu i próbują w trakcie.",
 x:"Na koniec spróbuj zupy i dopraw ją szczyptą soli i sokiem z cytryny.",
 f:"Sól nie tylko dodaje słoności: osłabia też odczuwanie goryczy, dlatego szczypta potrafi poprawić smak niektórych warzyw.",
 js:"Dodawanie odrobiny soli, pieprzu albo ziół, żeby jedzenie lepiej smakowało.",
 jl:"Doprawianie to dodawanie do jedzenia na przykład soli, pieprzu albo ziół. Dobry kucharz dodaje trochę, próbuje i dopiero wtedy decyduje, czy trzeba więcej. Odrobina wystarczy, żeby było w sam raz.",
 jx:"Mama dała mi spróbować zupy i zdecydować, czy trzeba ją jeszcze doprawić."},
{id:"cook_folding",cat:"cook",t:"Łączenie z pianą (delikatne mieszanie)",
 s:"Ostrożne łączenie lekkiego, napowietrzonego składnika z cięższą masą tak, by nie stracić powietrza.",
 l:"Tak łączy się ubitą pianę z białek albo bitą śmietanę z cięższą masą, na przykład przy musie, suflecie czy biszkopcie. Zamiast mieszać energicznie, przecina się masę szpatułką lub dużą łyżką przez środek, przesuwa po dnie i przekłada na wierzch, obracając przy tym miskę. W przepisach pisze się często: delikatnie wymieszać z pianą albo połączyć. Dzięki temu w masie zostaje jak najwięcej pęcherzyków powietrza, a wypiek jest lekki.",
 x:"Łącz pianę z czekoladą powoli, bo inaczej mus opadnie.",
 f:"Białka najlepiej ubijają się w idealnie czystej misce, bo nawet odrobina tłuszczu lub żółtka nie pozwala im zatrzymać powietrza; od dawna używa się też miedzianych misek, w których piana jest trwalsza.",
 js:"Bardzo delikatne mieszanie, żeby bąbelki zostały w środku.",
 jl:"Ubita piana z białek jest pełna bąbelków powietrza. Jeśli mieszasz ją mocno, bąbelki pękają. Dlatego kucharze mieszają bardzo delikatnie, podnosząc i obracając masę dużą łyżką.",
 jx:"Powoli i ostrożnie łączyłam bitą śmietanę z truskawkami."},
{id:"cook_pl_pierogi",cat:"cook",only:1,c:"Polska",t:"Pierogi",
 s:"Gotowane lub smażone pierożki z ciasta wypełnione farszem, jedno z najbardziej znanych dań kuchni polskiej.",
 l:"Pierogi robi się z cienko rozwałkowanego ciasta z mąki i wody, z którego wycina się krążki, nakłada farsz i skleja brzegi. Najpopularniejsze nadzienia to ziemniaki z twarogiem i cebulą, kapusta z grzybami, mięso oraz owoce, na przykład jagody czy truskawki. Zwykle się je gotuje, a potem okrasza masłem, cebulką lub skwarkami, czasem podsmaża. Podobne potrawy znają także inne kuchnie Europy Środkowej i Wschodniej. Na Wigilię w wielu domach podaje się pierogi z kapustą i grzybami.",
 x:"Babcia lepi pierogi z całą rodziną i zawsze robi więcej, żeby można je było zamrozić.",
 f:"Pierogi ruskie nie pochodzą z Rosji: nazwa nawiązuje do Rusi, dawnej krainy, której część leży dziś w zachodniej Ukrainie.",
 js:"Pierożki z ciasta z pysznym nadzieniem w środku.",
 jl:"Pierogi to kawałki ciasta złożone na pół, a w środku jest farsz: ziemniaki z serem, kapusta albo owoce. Lepienie pierogów z całą rodziną to świetna zabawa – każdy może zrobić swój kształt!",
 jx:"Na obiad były pierogi z jagodami polane śmietaną."},
{id:"cook_pl_bigos",cat:"cook",only:1,c:"Polska",t:"Bigos",
 s:"Tradycyjna polska potrawa z kiszonej i słodkiej kapusty, mięsa, kiełbasy i grzybów, długo duszona.",
 l:"Bigos to gęsta, aromatyczna potrawa z kapusty kiszonej, często z dodatkiem słodkiej, z różnymi rodzajami mięsa, kiełbasą, suszonymi grzybami, śliwkami i przyprawami, takimi jak ziele angielskie i liść laurowy. Dusi się go długo, a według wielu kucharzy smakuje najlepiej odgrzewany przez kilka dni. Każdy region, a nawet każda rodzina, ma własny przepis. Dawniej był daniem myśliwskim, zabieranym na polowania, bo łatwo go przechować i podgrzać.",
 x:"Na święta tata zawsze robi bigos dwa dni wcześniej, żeby się przegryzł.",
 f:"Bigos opisał Adam Mickiewicz w „Panu Tadeuszu”, w scenie po polowaniu, chwaląc jego smak, kolor i zapach.",
 js:"Polska potrawa z kapusty, mięsa i grzybów, która długo się gotuje.",
 jl:"Bigos to gęste danie z kapusty kiszonej, kiełbasy, mięsa i grzybów. Gotuje się go bardzo długo i w domu pięknie pachnie. Wiele osób mówi, że następnego dnia jest jeszcze smaczniejszy.",
 jx:"Kiedy wróciliśmy z sanek, w kuchni czekał gorący bigos."},
{id:"cook_pl_zurek",cat:"cook",only:1,c:"Polska",t:"Żurek",
 s:"Kwaśna zupa na zakwasie z mąki żytniej, często z białą kiełbasą i jajkiem.",
 l:"Żurek przygotowuje się na zakwasie, czyli fermentowanej przez kilka dni mieszance mąki żytniej, wody, czosnku i przypraw. Zakwas daje zupie charakterystyczny, przyjemnie kwaśny smak. Gotuje się ją na wywarze, często z białą kiełbasą lub wędzonką, doprawia majerankiem, a podaje z jajkiem na twardo, czasem z ziemniakami albo w chlebie. Jest jedną z najważniejszych potraw wielkanocnych. Bliski mu jest barszcz biały, gotowany na zakwasie pszennym.",
 x:"W Wielkanoc na stole zawsze jest żurek z białą kiełbasą i jajkiem.",
 f:"Dawniej na koniec Wielkiego Postu urządzano w niektórych regionach „pogrzeb żuru”: garnek z żurem, jedzonym przez cały post, zakopywano albo rozbijano, ciesząc się z nadchodzących świąt.",
 js:"Kwaśna zupa z jajkiem i kiełbasą, jedzona zwłaszcza na Wielkanoc.",
 jl:"Żurek to zupa, która jest trochę kwaśna. Ten smak bierze się z zakwasu zrobionego z mąki i wody, który stoi kilka dni w cieple. Do żurku dodaje się kiełbasę i jajko. Wiele rodzin je go na Wielkanoc.",
 jx:"Na śniadanie wielkanocne zjadłam żurek w chlebowej misce."},
{id:"cook_pl_tlusty_czwartek",cat:"cook",only:1,c:"Polska",t:"Tłusty czwartek",
 s:"Ostatni czwartek przed Wielkim Postem, kiedy w Polsce tradycyjnie je się pączki i faworki.",
 l:"Tłusty czwartek przypada w ostatni czwartek karnawału, sześć dni przed Środą Popielcową. Tego dnia w całej Polsce kupuje się i smaży pączki, najczęściej z nadzieniem różanym lub innym, oraz faworki, nazywane też chrustem. Przed cukierniami ustawiają się kolejki, a w szkołach i biurach częstuje się słodyczami. Zwyczaj wiąże się z dawnym ucztowaniem przed postem, w którym rezygnowano z tłustych potraw.",
 x:"W tłusty czwartek cała klasa przyniosła pączki dla pani.",
 f:"Data tłustego czwartku co roku się zmienia, bo zależy od daty Wielkanocy.",
 js:"Wesoły dzień, kiedy w Polsce je się pączki.",
 jl:"Tłusty czwartek to dzień przed postem, kiedy prawie wszyscy w Polsce jedzą pączki. Są z marmoladą, budyniem albo konfiturą różaną. Pod cukierniami stoją długie kolejki, a w domu pachnie słodko.",
 jx:"W tłusty czwartek zjadłem pączka z różą i miałem cukier puder na nosie."},
/* ---------- MEDYCYNA (+6) ---------- */
{id:"m_virus_bacteria",cat:"med",t:"Wirus i bakteria",
 s:"Dwa różne rodzaje zarazków: bakterie to maleńkie żywe komórki, a wirusy to jeszcze mniejsze cząstki, które namnażają się tylko w komórkach.",
 l:"Bakterie to organizmy jednokomórkowe, które potrafią same żyć i się rozmnażać; większość jest nieszkodliwa lub pożyteczna, jak te w naszych jelitach, ale niektóre wywołują zakażenia, na przykład anginę paciorkowcową. Wirusy są dużo mniejsze i nie mogą się namnażać, dopóki nie wnikną do żywej komórki i nie zmuszą jej do robienia swoich kopii; to one wywołują przeziębienie, grypę czy ospę wietrzną. Ta różnica jest ważna, bo antybiotyki działają na bakterie, a na wirusy nie, więc nie pomagają na przeziębienie.",
 x:"Lekarka wyjaśniła, że to infekcja wirusowa, więc antybiotyk nic nie da.",
 f:"Większość wirusów jest zbyt mała, by zobaczyć je w zwykłym mikroskopie świetlnym; naukowcy wyraźnie zobaczyli je dopiero dzięki mikroskopowi elektronowemu w dwudziestym wieku.",
 js:"Dwa rodzaje maleńkich zarazków; antybiotyki działają tylko na bakterie.",
 jl:"Zarazki są tak małe, że ich nie widać. Bakterie to maleńkie żyjątka, a wiele z nich jest dla nas dobrych. Wirusy są jeszcze mniejsze i żeby się rozmnożyć, muszą wejść do komórek naszego ciała. Katar zwykle wywołuje wirus.",
 jx:"Pani powiedziała, że przeziębienie wywołuje wirus, więc trzeba odpoczywać i pić dużo wody."},
{id:"m_dehydration",cat:"med",t:"Odwodnienie",
 s:"Stan, w którym organizm traci więcej wody, niż otrzymuje.",
 l:"Do odwodnienia dochodzi, gdy tracimy więcej płynów, niż pijemy, na przykład przez pocenie się w upale lub przy wysiłku, gorączkę, wymioty czy biegunkę. Pierwsze objawy to pragnienie, suchość w ustach, zmęczenie, ból głowy, ciemny mocz i rzadsze oddawanie moczu. Niemowlęta, małe dzieci i osoby starsze odwadniają się łatwiej. Łagodne odwodnienie zwykle mija po wypiciu płynów; doustne płyny nawadniające uzupełniają też utracone sole. Ciężkie odwodnienie, ze splątaniem, omdleniem czy brakiem moczu, to stan nagły.",
 x:"Po długiej wędrówce w słońcu bolała go głowa z odwodnienia.",
 f:"Doustny płyn nawadniający, prosta mieszanka wody, soli i cukru, uratował miliony istnień, zwłaszcza dzieci chorych na biegunkę.",
 js:"Kiedy w twoim ciele jest za mało wody.",
 jl:"Twoje ciało potrzebuje wody, żeby dobrze działać. W upale, podczas biegania albo choroby tracisz wodę, na przykład kiedy się pocisz. Jeśli pijesz za mało, możesz być zmęczony, boleć cię może głowa i bardzo chce ci się pić. To odwodnienie.",
 jx:"Po treningu wypiłem dużą butelkę wody, żeby się nie odwodnić."},
{id:"m_concussion",cat:"med",t:"Wstrząśnienie mózgu",
 s:"Łagodny uraz mózgu po uderzeniu lub gwałtownym wstrząsie głowy, który przejściowo zaburza jego działanie.",
 l:"Wstrząśnienie mózgu może nastąpić po uderzeniu w głowę albo gwałtownym szarpnięciu ciała, na przykład przy upadku, w wypadku czy w sportach kontaktowych. Nie trzeba przy tym stracić przytomności. Objawy to między innymi ból i zawroty głowy, dezorientacja, kłopoty z pamięcią, nudności, nadwrażliwość na światło i poczucie, że coś jest nie tak. Większość osób wraca do zdrowia dzięki odpoczynkowi i stopniowemu powrotowi do aktywności, ale po urazie trzeba przerwać grę i dać się zbadać. Powtarzające się wymioty, narastający ból głowy czy senność wymagają pilnej pomocy.",
 x:"Po zderzeniu na boisku zawodnika zdjęto z murawy, żeby sprawdzić, czy nie ma wstrząśnienia mózgu.",
 f:"W wielu sportach obowiązuje zasada: w razie wątpliwości zawodnik schodzi z boiska i nie wraca do gry tego dnia.",
 js:"Uraz głowy po mocnym uderzeniu, przez który może się kręcić w głowie.",
 jl:"Jeśli mocno uderzysz się w głowę, twój mózg może się wstrząsnąć. Może ci się kręcić w głowie, być niedobrze albo boleć głowa. Zawsze powiedz dorosłemu, jeśli uderzyłeś się w głowę, i odpocznij od zabawy tego dnia.",
 jx:"Kiedy Olek uderzył się w głowę na placu zabaw, pani sprawdziła, czy dobrze się czuje."},
{id:"m_ecg",cat:"med",t:"EKG (elektrokardiogram)",
 s:"Szybkie i bezbolesne badanie, które zapisuje elektryczną pracę serca.",
 l:"Elektrokardiogram, w skrócie EKG, zapisuje maleńkie sygnały elektryczne, które sprawiają, że serce bije. Na klatce piersiowej, rękach i nogach przykleja się lub przypina małe elektrody połączone z aparatem, który rysuje sygnały jako falistą linię. Badanie trwa kilka minut i nie boli. Lekarze sprawdzają w nim rytm i częstość pracy serca i szukają oznak problemów, na przykład zawału. EKG tylko odbiera prąd z serca; nie wysyła prądu do ciała.",
 x:"Na izbie przyjęć zrobili mu EKG z powodu bólu w klatce piersiowej.",
 f:"Holenderski lekarz Willem Einthoven skonstruował praktyczny elektrokardiograf na początku dwudziestego wieku i otrzymał za to Nagrodę Nobla w 1924 roku.",
 js:"Badanie, które rysuje, jak bije twoje serce.",
 jl:"Serce pracuje dzięki maleńkim sygnałom elektrycznym. Podczas EKG pielęgniarka przykleja ci na klatce piersiowej, rękach i nogach małe naklejki. Aparat odczytuje sygnały i rysuje zygzak. To wcale nie boli.",
 jx:"Dziadek miał robione EKG i powiedział, że naklejki były tylko trochę zimne."},
{id:"m_pulse",cat:"med",t:"Tętno (puls)",
 s:"Rytmiczne uderzenia wyczuwalne w tętnicy przy każdym skurczu serca, zwykle liczone na minutę.",
 l:"Każde uderzenie serca wtłacza krew do tętnic i wywołuje falę, którą wyczuwamy jako tętno, na przykład po wewnętrznej stronie nadgarstka, poniżej kciuka, albo z boku szyi. Licząc uderzenia przez minutę, poznajemy częstość pracy serca. Rośnie ona podczas wysiłku, gorączki, emocji czy strachu, a spada w spoczynku i we śnie. Lekarze sprawdzają też, czy tętno jest miarowe. Wytrenowani sportowcy mają często wolniejsze tętno spoczynkowe, bo silne serce przy każdym skurczu pompuje więcej krwi.",
 x:"Pielęgniarka liczyła mu tętno, patrząc na zegarek.",
 f:"Tętno mierzy się dwoma palcami, a nie kciukiem, bo w kciuku wyczuwa się własne tętno, które może pomylić liczenie.",
 js:"Uderzenia, które czujesz na nadgarstku albo szyi, kiedy serce pompuje krew.",
 jl:"Połóż delikatnie dwa palce po wewnętrznej stronie nadgarstka, pod kciukiem. Czujesz takie małe puk, puk, puk? To twoje tętno! Bierze się z pracy serca. Po bieganiu jest szybsze.",
 jx:"Na WF-ie mierzyliśmy tętno przed biegiem i po biegu."},
{id:"m_pl_sor",cat:"med",only:1,c:"Polska",t:"SOR (Szpitalny Oddział Ratunkowy)",
 s:"Szpitalny oddział, na którym udziela się pomocy w nagłych, zagrażających życiu lub zdrowiu stanach.",
 l:"SOR przyjmuje osoby w stanach nagłych, takich jak ból w klatce piersiowej, duszność, silne krwawienie, poważne urazy czy objawy udaru. Nie potrzeba skierowania. Pacjentów ocenia się w triażu i przyjmuje według pilności, a nie kolejności przybycia, dlatego przy lżejszych dolegliwościach czeka się długo. Z problemami pilnymi, ale niegroźnymi dla życia, w nocy i w dni wolne lepiej zgłosić się do nocnej i świątecznej opieki zdrowotnej, a w dzień do lekarza rodzinnego.",
 x:"Złamał rękę na deskorolce i spędził wieczór na SOR-ze.",
 f:"Numer alarmowy sto dwanaście działa w całej Unii Europejskiej, a w Polsce wciąż można też dzwonić pod dziewięćset dziewięćdziesiąt dziewięć, numer pogotowia ratunkowego.",
 js:"Oddział w szpitalu, który od razu pomaga osobom bardzo chorym albo poważnie rannym.",
 jl:"SOR to część szpitala, która działa w dzień i w nocy. Trafiają tam ludzie, którym stało się coś poważnego, na przykład złamali rękę albo nie mogą oddychać. Lekarze najpierw pomagają tym, z którymi jest najgorzej.",
 jx:"Kiedy Staś spadł z drabinek i mocno uderzył się w rękę, mama zawiozła go na SOR."},
/* ---------- PRAWO (+6) ---------- */
{id:"l_constitution",cat:"law",c:"Polska",t:"Konstytucja",
 s:"Najważniejszy akt prawny państwa, określający jego ustrój, władze oraz prawa i wolności obywateli.",
 l:"Konstytucja Rzeczypospolitej Polskiej z 2 kwietnia 1997 roku określa, jak działa państwo: dzieli władzę na ustawodawczą, czyli Sejm i Senat, wykonawczą, czyli prezydenta i Radę Ministrów, oraz sądowniczą, czyli sądy i trybunały. Opisuje też prawa i wolności człowieka, na przykład wolność słowa, prawo do nauki i do sądu. Wszystkie ustawy muszą być z nią zgodne. Uchwaliło ją Zgromadzenie Narodowe, a obywatele zatwierdzili w referendum; jej zmiana wymaga specjalnej procedury.",
 x:"Na lekcji wiedzy o społeczeństwie czytaliśmy rozdział konstytucji o prawach i wolnościach.",
 f:"Konstytucja 3 maja z 1791 roku była pierwszą nowoczesną spisaną konstytucją w Europie i drugą na świecie, po amerykańskiej.",
 js:"Najważniejsze prawo w państwie, które mówi, jak kraj ma działać.",
 jl:"Konstytucja to najważniejsza księga zasad w kraju. Mówi, kto ustala prawo, kto rządzi, a kto sądzi, i jakie prawa ma każdy człowiek. Inne przepisy muszą się z nią zgadzać.",
 jx:"W naszej klasie napisaliśmy konstytucję samorządu z zasadami, na które wszyscy się zgodzili."},
{id:"l_tenancy",cat:"law",c:"Polska",t:"Umowa najmu",
 s:"Umowa, w której wynajmujący oddaje rzecz, na przykład mieszkanie, do używania w zamian za czynsz.",
 l:"Umowa najmu mieszkania określa wysokość czynszu i termin płatności, czas trwania najmu, kto odpowiada za naprawy i jak można ją wypowiedzieć. Podstawowe zasady opisuje Kodeks cywilny, a ochronę lokatorów dodatkowo ustawa o ochronie praw lokatorów. Właściciel często pobiera kaucję na pokrycie ewentualnych szkód i zaległości. Szczególną formą jest najem okazjonalny, zawierany z oświadczeniem najemcy złożonym u notariusza, który ułatwia właścicielowi odzyskanie mieszkania po zakończeniu umowy.",
 x:"Przeczytaj dokładnie umowę najmu, zanim ją podpiszesz.",
 f:"Według ustawy o ochronie praw lokatorów kaucja za mieszkanie nie może przekroczyć dwunastokrotności miesięcznego czynszu.",
 js:"Umowa o wynajęciu mieszkania.",
 jl:"Niektóre rodziny mieszkają w mieszkaniu, które należy do kogoś innego, i co miesiąc płacą mu pieniądze. Podpisują wtedy umowę z zasadami: ile płacić i kto naprawia to, co się zepsuje. To umowa najmu.",
 jx:"Kiedy przeprowadzaliśmy się do nowego mieszkania, mama podpisała umowę najmu."},
{id:"l_alibi",cat:"law",c:"Polska",t:"Alibi",
 s:"Okoliczność, że w chwili przestępstwa ktoś był w innym miejscu, więc nie mógł go popełnić.",
 l:"Alibi to dowód, że podejrzany lub oskarżony był gdzie indziej, gdy doszło do przestępstwa. Mogą je potwierdzić świadkowie, paragony, bilingi, logowania telefonu czy nagrania z kamer. W polskim procesie karnym nie musi on udowadniać swojej niewinności, bo działa domniemanie niewinności, ale wskazanie alibi pomaga szybko wyjaśnić sprawę. Potocznie alibi oznacza też każdą wymówkę, ale w prawie chodzi właśnie o przebywanie w innym miejscu.",
 x:"Jego alibi potwierdziło nagranie z kamery w restauracji.",
 f:"Alibi to łacińskie słowo i znaczy gdzie indziej.",
 js:"Dowód, że ktoś był w innym miejscu, kiedy coś się stało.",
 jl:"W kryminałach ktoś mówi: to nie mogłem być ja, byłem wtedy w kinie! Jeśli ludzie go tam widzieli, to jest jego alibi. Pokazuje, że był gdzie indziej.",
 jx:"Tomek miał mocne alibi: kiedy zniknął sernik, był na treningu."},
{id:"l_verdict",cat:"law",c:"Polska",t:"Wyrok",
 s:"Orzeczenie sądu rozstrzygające sprawę co do istoty, na przykład o winie oskarżonego lub o żądaniu pozwu.",
 l:"Wyrokiem sąd kończy sprawę w pierwszej instancji: w sprawie karnej uznaje oskarżonego za winnego i wymierza karę albo go uniewinnia, w cywilnej uwzględnia pozew lub go oddala. W Polsce nie ma ławy przysięgłych: orzeka sędzia, a w niektórych sprawach skład z udziałem ławników. Wyrok ogłasza się publicznie, a strony mogą złożyć apelację. Wyrok staje się prawomocny, gdy nie można go już zaskarżyć zwykłym środkiem odwoławczym.",
 x:"Sąd ogłosił wyrok uniewinniający i oskarżony wyszedł z sali wolny.",
 f:"Polskie sądy wydają wyroki w imieniu Rzeczypospolitej Polskiej, a podczas ich ogłaszania wszyscy na sali wstają.",
 js:"Decyzja sądu na końcu sprawy.",
 jl:"Na końcu sprawy w sądzie sędzia ogłasza decyzję. Mówi na przykład, czy ktoś zrobił coś złego i co ma się teraz stać. Ta decyzja nazywa się wyrokiem. Wszyscy wtedy wstają.",
 jx:"Na lekcji zagraliśmy rozprawę, a „sędzia” Ola ogłosiła wyrok."},
{id:"l_trademark",cat:"law",c:"Polska",t:"Znak towarowy",
 s:"Oznaczenie, na przykład nazwa, logo czy hasło, które odróżnia towary lub usługi jednej firmy od innych.",
 l:"Znak towarowy pomaga klientom rozpoznać, od kogo pochodzi produkt. W Polsce można go zarejestrować w Urzędzie Patentowym Rzeczypospolitej Polskiej, a dla całej Unii Europejskiej w unijnym urzędzie EUIPO w Alicante. Rejestracja daje prawo wyłącznego używania znaku i zakazania innym używania znaku identycznego lub łudząco podobnego dla podobnych towarów. Ochrona trwa dziesięć lat i można ją przedłużać. Symbol litery R w kółku powinien oznaczać tylko znak zarejestrowany.",
 x:"Piekarnia zarejestrowała swoją nazwę jako znak towarowy, zanim otworzyła kolejne sklepy.",
 f:"Ochronę znaku towarowego można przedłużać na kolejne dziesięcioletnie okresy bez ograniczeń, więc niektóre znaki są chronione od ponad stu lat.",
 js:"Specjalna nazwa albo logo, które pokazuje, która firma coś zrobiła.",
 jl:"Wiele firm ma swoje logo albo specjalną nazwę. Znak towarowy oznacza, że inne firmy nie mogą go skopiować. Dzięki temu wiemy, która firma naprawdę zrobiła rzecz, którą kupujemy.",
 jx:"W klasie wymyśliliśmy markę soku i narysowaliśmy jej znak towarowy."},
{id:"l_pl_komornik",cat:"law",only:1,c:"Polska",j:false,t:"Komornik sądowy",
 s:"Funkcjonariusz publiczny działający przy sądzie rejonowym, który przymusowo wykonuje orzeczenia, na przykład ściąga długi.",
 l:"Komornik sądowy prowadzi egzekucję, gdy dłużnik dobrowolnie nie spełnia obowiązku, na przykład nie spłaca długu albo nie płaci alimentów. Działa na wniosek wierzyciela, który musi mieć tytuł wykonawczy, najczęściej wyrok sądu z klauzulą wykonalności. Komornik może zająć część wynagrodzenia, rachunek bankowy lub majątek, ale prawo chroni pewną część dochodu i niezbędne rzeczy. Ma obowiązek działać zgodnie z prawem, a na jego czynności można złożyć skargę do sądu.",
 x:"Po wyroku wierzyciel złożył wniosek do komornika o wszczęcie egzekucji.",
 f:"Dawniej komornikiem nazywano też chłopa bez ziemi, który mieszkał kątem w cudzej chałupie, w komorze, i najmował się do pracy."},
/* ---------- JĘZYK OGÓLNY (+6) ---------- */
{id:"g_antonym",cat:"gen",t:"Antonim (wyraz przeciwstawny)",
 s:"Wyraz o znaczeniu przeciwnym do innego wyrazu.",
 l:"Antonimy to pary takie jak gorący i zimny, otwarty i zamknięty, kupić i sprzedać. Niektóre mają wiele stopni pośrednich, jak ciepły i chłodny, inne wykluczają się całkowicie, jak żywy i martwy. Część przeciwieństw opisuje tę samą sytuację z dwóch stron, jak nauczyciel i uczeń. W polszczyźnie wiele antonimów tworzy się przedrostkiem nie-, na przykład szczęście i nieszczęście albo możliwy i niemożliwy. Pisarze używają ich do budowania kontrastu.",
 x:"Antonimem słowa hojny jest skąpy.",
 f:"Polskie słowo pożyczyć może znaczyć zarówno dać komuś na chwilę, jak i wziąć od kogoś, więc samo bywa swoim przeciwieństwem.",
 js:"Słowo, które znaczy coś odwrotnego, jak duży i mały.",
 jl:"Antonimy to słowa przeciwne: góra i dół, wesoły i smutny, szybki i wolny. Można się bawić: jedna osoba mówi słowo, a druga szybko podaje jego przeciwieństwo.",
 jx:"Antonimem słowa głośny jest cichy – jak nasza klasa po dzwonku!"},
{id:"g_homophone",cat:"gen",t:"Homofon",
 s:"Wyraz, który brzmi tak samo jak inny, ale ma inne znaczenie i często inną pisownię.",
 l:"Homofony to wyrazy takie jak morze i może, buk i Bóg albo kot i kod, które w mowie brzmią tak samo, a znaczą co innego. W polszczyźnie jest ich sporo, bo te same głoski zapisujemy różnie: rz i ż, ó i u, ch i h, a na końcu wyrazu dźwięczne spółgłoski wymawiamy bezdźwięcznie. W mowie znaczenie wynika z kontekstu, w piśmie – z ortografii. Dla osób słuchających tekstów czytanych na głos jasny kontekst jest więc szczególnie ważny.",
 x:"Morze i może to homofony: brzmią tak samo, a znaczą coś zupełnie innego.",
 f:"Nazwa pochodzi od greckich słów homos, taki sam, i phone, dźwięk.",
 js:"Słowa, które brzmią tak samo, ale znaczą co innego, jak morze i może.",
 jl:"Niektóre słowa brzmią dokładnie tak samo, ale pisze się je inaczej i znaczą coś innego. Morze to woda z falami, a może mówimy, kiedy nie jesteśmy pewni. To homofony. Dlatego ortografia jest taka ważna!",
 jx:"Pani napisała na tablicy buk i Bóg, żeby pokazać nam homofony."},
{id:"g_acronym",cat:"gen",t:"Skrótowiec (akronim)",
 s:"Wyraz utworzony z pierwszych liter lub głosek kilku innych wyrazów.",
 l:"Skrótowce powstają z początkowych liter lub sylab nazwy. Jedne czytamy jak zwykłe słowa, na przykład ZUS czy PAN, inne literami, na przykład PKP, czyli pe-ka-pe. W polszczyźnie wiele skrótowców się odmienia: pracuje w ZUS-ie, jedzie PKS-em, a ich rodzaj zwykle zależy od głównego wyrazu nazwy. Niektóre tak się zadomowiły, że piszemy je małymi literami, jak pekaes. Pisząc dla słuchaczy, warto rozwinąć skrótowiec przy pierwszym użyciu.",
 x:"Radar to skrótowiec od angielskich słów oznaczających wykrywanie i namierzanie radiowe.",
 f:"Słowo laser też jest skrótowcem, od angielskiego określenia wzmacniania światła przez wymuszoną emisję promieniowania.",
 js:"Krótkie słowo zrobione z pierwszych liter innych słów.",
 jl:"Czasem długie nazwy skraca się, biorąc pierwszą literę każdego słowa. Tak powstają skrótowce. Na przykład PKP to Polskie Koleje Państwowe. Niektóre czyta się jak zwykłe słowa!",
 jx:"Wymyśliliśmy skrótowiec dla naszego klubu: KOT, czyli Klub Odkrywców Tajemnic."},
{id:"g_alliteration",cat:"gen",t:"Aliteracja",
 s:"Powtórzenie tej samej głoski na początku kilku sąsiednich wyrazów.",
 l:"Aliteracja polega na powtarzaniu tej samej głoski na początku wyrazów stojących blisko siebie, jak w zdaniu: król Karol kupił królowej Karolinie korale koloru koralowego. Dzięki niej zdanie ma rytm i łatwo zapada w pamięć, dlatego aliterację lubią poeci, autorzy łamańców językowych, nagłówków i haseł reklamowych. Liczy się dźwięk, a nie litera. Użyta w nadmiarze brzmi zabawnie, co jest częścią uroku łamańców.",
 x:"Król Karol kupił królowej Karolinie korale koloru koralowego to znany przykład aliteracji.",
 f:"Słynny łamaniec o chrząszczu, który brzmi w trzcinie w Szczebrzeszynie, pochodzi z wiersza Jana Brzechwy; w Szczebrzeszynie stoi dziś pomnik tego chrząszcza.",
 js:"Kiedy kilka słów obok siebie zaczyna się tym samym dźwiękiem.",
 jl:"Powiedz szybko: sroka siedzi sobie spokojnie. Wszystkie słowa zaczynają się tak samo! To aliteracja. Łamańce językowe używają jej, żeby język się plątał.",
 jx:"W wierszyku Ania napisała: bardzo bystre bobry budują bobrze bramy."},
{id:"g_rhetorical_question",cat:"gen",t:"Pytanie retoryczne",
 s:"Pytanie zadane dla efektu, na które mówiący nie oczekuje odpowiedzi.",
 l:"Pytanie retoryczne służy do podkreślenia myśli, wyrażenia emocji albo skłonienia słuchaczy do refleksji, a nie do zdobycia informacji. Kto by nie chciał dnia wolnego? znaczy po prostu, że każdy by chciał. Mówcy i pisarze używają takich pytań, żeby zaangażować odbiorców, podkreślić ważną myśl albo wyrazić zdziwienie czy irytację. Ponieważ odpowiedź jest oczywista, odpowiadanie na nie brzmi zabawnie lub zuchwale. Pytanie: która to jest godzina? zadane spóźnialskiemu zwykle nie dotyczy zegarka.",
 x:"Czy trawa jest zielona? odpowiedział, czyli: oczywiście, że tak.",
 f:"Retoryka, czyli sztuka przekonującego przemawiania, była w starożytnej Grecji i Rzymie jednym z głównych przedmiotów nauki.",
 js:"Pytanie, na które nikt nie czeka na odpowiedź.",
 jl:"Czasem ktoś zadaje pytanie, ale wcale nie chce odpowiedzi. Kiedy mama mówi: ile razy mam ci powtarzać?, nie chce usłyszeć liczby! Chce coś podkreślić. To pytanie retoryczne.",
 jx:"Kto chce zadanie domowe na weekend? zażartowała pani – to było pytanie retoryczne!"},
{id:"g_pl_zdrobnienia",cat:"gen",only:1,c:"Polska",t:"Zdrobnienie",
 s:"Wyraz utworzony od innego, który nazywa coś mniejszego lub wyraża czułość, na przykład kotek od kot.",
 l:"Polszczyzna jest pełna zdrobnień. Tworzymy je przyrostkami, takimi jak -ek, -ka, -ko czy -czek: dom i domek, ręka i rączka, słońce i słoneczko. Zdrobnienia często nie mówią o rozmiarze, lecz o uczuciu, dlatego mamy Anię, Kasię i Jasia, a w sklepie słyszymy: może jeszcze chlebek? Można je nawet stopniować: kot, kotek, koteczek. Czasem zdrobnienie zmienia znaczenie, bo nóżka stołu to nie mała noga.",
 x:"Babcia zawsze pyta, czy zjem jeszcze zupkę i kawałeczek ciasta.",
 f:"Po polsku zdrabniamy nawet przymiotniki i przysłówki, na przykład malutki, cieplutki czy cichutko.",
 js:"Słowo, które brzmi czule albo mówi o czymś małym, jak kotek albo domek.",
 jl:"Kiedy mówimy kotek zamiast kot albo misiaczek zamiast miś, używamy zdrobnień. Brzmią czule i miło. Polacy bardzo je lubią – nawet imiona zdrabniamy: Ania, Kasia, Kuba.",
 jx:"Moja młodsza siostra mówi na swojego misia misiaczek."},
/* ---------- PSYCHOLOGIA (+6) ---------- */
{id:"p_self_compassion",cat:"psy",t:"Współczucie dla siebie (samowspółczucie)",
 s:"Traktowanie siebie z taką samą życzliwością i zrozumieniem, jakie okazalibyśmy dobremu przyjacielowi.",
 l:"Współczucie dla siebie oznacza reagowanie na własne błędy i trudne chwile ciepłem zamiast surową krytyką. Psycholożka Kristin Neff opisuje trzy jego elementy: życzliwość wobec siebie, pamiętanie, że trudności są częścią ludzkiego życia, i uważne zauważanie bolesnych uczuć bez dawania się im pochłonąć. To nie użalanie się nad sobą ani pobłażanie sobie; osobom, które są dla siebie łagodniejsze, często łatwiej uczyć się na błędach i próbować dalej.",
 x:"Zamiast nazwać się głupią, przypomniała sobie o współczuciu dla siebie: każdy się myli.",
 f:"Proste ćwiczenie polega na zapytaniu siebie: co powiedziałabym przyjaciółce w tej sytuacji? – i powiedzeniu tego samej sobie.",
 js:"Bycie miłym dla siebie, tak jak dla dobrego przyjaciela.",
 jl:"Kiedy kolega się pomyli, możesz powiedzieć: nie martw się, następnym razem pójdzie lepiej. Współczucie dla siebie to mówienie do siebie tak samo łagodnie, kiedy sam się pomylisz.",
 jx:"Kiedy Mia źle napisała słowo, powiedziała sobie: nic się nie stało, ciągle się uczę."},
{id:"p_habit",cat:"psy",t:"Nawyk",
 s:"Zachowanie powtarzane tak często w tej samej sytuacji, że dzieje się prawie automatycznie.",
 l:"Nawyki powstają, gdy powtarzamy czynność w podobnych okolicznościach tak długo, aż przestaje wymagać namysłu, jak mycie zębów po śniadaniu czy sięganie po telefon, gdy tylko usiądziemy. Psychologowie opisują często pętlę: sygnał, czynność i nagrodę, która zachęca do powtórzenia. Nawyki oszczędzają wysiłek umysłowy, ale sprawiają też, że trudno zmienić niekorzystne zachowania. Nowy nawyk najłatwiej zbudować, łącząc go z już istniejącym sygnałem i zaczynając od bardzo małego kroku.",
 x:"Buty do biegania przy drzwiach pomogły jej wyrobić nawyk porannego spaceru.",
 f:"Słowo nawyk jest spokrewnione z czasownikami przywyknąć i odwyknąć.",
 js:"Coś, co robisz tak często, że robisz to bez myślenia.",
 jl:"Myjesz zęby, nawet o tym nie myśląc? To nawyk. Kiedy robisz coś wiele razy o tej samej porze, twój mózg się tego uczy i potem przychodzi to łatwo.",
 jx:"Pakowanie plecaka wieczorem stało się moim nawykiem."},
{id:"p_introversion",cat:"psy",t:"Introwersja i ekstrawersja",
 s:"Cechy osobowości opisujące, czy ktoś łatwiej odzyskuje energię w spokoju i ciszy, czy wśród ludzi i w ruchu.",
 l:"Introwersja i ekstrawersja to dwa końce skali, a nie dwie szufladki. Osoby bardziej introwertyczne często wolą mniejsze grupy i czas w ciszy, a po wielu spotkaniach czują się zmęczone; bardziej ekstrawertyczne zwykle czerpią energię z towarzystwa i gwaru. Wielu ludzi plasuje się pośrodku. Introwersja to nie nieśmiałość, czyli lęk przed oceną innych. Żadna z tych cech nie jest lepsza; każda wnosi inne mocne strony.",
 x:"Jako introwertyk lubi imprezy, ale potrzebuje potem spokojnego wieczoru.",
 f:"Szwajcarski psychiatra Carl Gustav Jung spopularyzował pojęcia introwersji i ekstrawersji w książce „Typy psychologiczne” z 1921 roku.",
 js:"Jedni zbierają energię wśród ludzi, inni w spokoju i ciszy.",
 jl:"Niektórzy uwielbiają duże przyjęcia i mają mnóstwo energii, kiedy są z wieloma kolegami. Inni wolą bawić się z jednym przyjacielem albo poczytać w ciszy. Jedno i drugie jest w porządku! Ludzie są po prostu różni.",
 jx:"Po głośnych urodzinach Ela lubiła poczytać w swoim pokoju."},
{id:"p_sunk_cost",cat:"psy",t:"Efekt utopionych kosztów",
 s:"Trwanie przy czymś tylko z powodu tego, co już w to włożyliśmy, choć lepiej byłoby przestać.",
 l:"Koszty utopione to czas, pieniądze lub wysiłek, które już wydaliśmy i których nie odzyskamy. Efekt utopionych kosztów pojawia się, gdy to one, a nie przyszłe korzyści, kierują decyzją, na przykład gdy siedzimy na fatalnym filmie, bo bilet był drogi. Rozsądna decyzja patrzy na to, co będzie od teraz. Wpadamy w tę pułapkę między innymi dlatego, że rezygnacja przypomina przyznanie się do straty. Gdy zauważymy ten mechanizm, łatwiej zmienić kurs.",
 x:"Zapłaciłem już za kurs, ale chodzenie na niego, choć go nie znosiłem, to był efekt utopionych kosztów.",
 f:"Bywa nazywany błędem Concorde’a, od naddźwiękowego samolotu pasażerskiego, którego budowę kontynuowano mimo rosnących wątpliwości, czy kiedykolwiek się zwróci.",
 js:"Robienie czegoś dalej tylko dlatego, że już się zaczęło, choć to już nie jest dobre.",
 jl:"Wyobraź sobie, że grasz w bardzo nudną grę już godzinę. Grasz dalej tylko dlatego, że szkoda ci tej godziny, choć wolałbyś przestać. To efekt utopionych kosztów.",
 jx:"Przestałam czytać nudną książkę w połowie – nie dałam się efektowi utopionych kosztów!"},
{id:"p_hyperfocus",cat:"psy",t:"Hiperskupienie (hiperfokus)",
 s:"Stan bardzo silnej i długiej koncentracji na jednej czynności, często z utratą poczucia czasu i otoczenia.",
 l:"Hiperskupienie to takie pochłonięcie czymś ciekawym, że wszystko inne znika, czasem na wiele godzin. Opisuje je wiele osób z ADHD i wiele osób autystycznych, co pokazuje, że ADHD to nie po prostu brak uwagi, lecz trudność w jej kierowaniu. Hiperskupienie bywa prawdziwą siłą w pracy twórczej, nauce i rozwiązywaniu problemów. Jego minusem jest zapominanie o jedzeniu, przerwach czy spotkaniach, dlatego niektórzy ustawiają alarmy i przypomnienia.",
 x:"W hiperskupieniu programował do trzeciej w nocy i nie zauważył, która godzina.",
 f:"Hiperskupienie przypomina stan przepływu opisywany przez psychologów, ale często trudniej je dowolnie zacząć i przerwać.",
 js:"Takie zajęcie się czymś, co kochasz, że zapominasz o wszystkim innym.",
 jl:"Czasem tak wciągnie cię budowanie, rysowanie albo czytanie, że nie słyszysz, jak ktoś cię woła. Niektórym mózgom zdarza się to często. To hiperskupienie. Pomaga robić niesamowite rzeczy, a minutnik przypomina o jedzeniu i odpoczynku.",
 jx:"Maks był w hiperskupieniu nad klockami i nie usłyszał wołania na obiad."},
{id:"p_pl_poradnia",cat:"psy",only:1,c:"Polska",t:"Poradnia psychologiczno-pedagogiczna",
 s:"Publiczna placówka, która bezpłatnie pomaga dzieciom, uczniom, rodzicom i nauczycielom w sprawach rozwoju i nauki.",
 l:"W poradni psychologiczno-pedagogicznej pracują psycholodzy, pedagodzy, logopedzi i inni specjaliści. Prowadzą diagnozy, na przykład dysleksji czy trudności w nauce, terapię, zajęcia i konsultacje dla rodzin. Poradnia wydaje opinie, które pomagają dostosować wymagania w szkole, oraz orzeczenia, na przykład o potrzebie kształcenia specjalnego. Korzystanie z poradni jest dobrowolne i bezpłatne, a zgłasza się do niej zwykle rodzic, bez skierowania.",
 x:"Po badaniu w poradni Kuba dostał opinię, dzięki której ma więcej czasu na sprawdzianach.",
 f:"Poradnie działają w każdym powiecie, a o pomoc mogą się do nich zwrócić także pełnoletni uczniowie.",
 js:"Miejsce, gdzie specjaliści pomagają dzieciom w nauce i w trudnych sprawach.",
 jl:"W poradni pracują mili specjaliści, na przykład psycholog albo logopeda. Pomagają dzieciom, którym coś sprawia trudność: czytanie, mówienie albo trudne uczucia. Można tam przyjść z rodzicem i porozmawiać albo zrobić ciekawe zadania.",
 jx:"W poradni pani logopeda bawiła się ze mną w ćwiczenia z literą r."},
/* ---------- BIZNES (+6) ---------- */
{id:"b_target_audience",cat:"biz",t:"Grupa docelowa",
 s:"Konkretna grupa ludzi, do której jest skierowany produkt, usługa lub komunikat.",
 l:"Grupę docelową opisuje się cechami takimi jak wiek, zainteresowania, potrzeby, miejsce zamieszkania czy dochody. Gdy firma ją zna, łatwiej jej zdecydować, co oferować, jak ustalić cenę, gdzie się reklamować i jakim językiem mówić. Sklep ze sprzętem do deskorolki i doradca emerytalny mówią do zupełnie innych ludzi. Wybór grupy docelowej nie oznacza ignorowania innych, tylko skupienie ograniczonego czasu i pieniędzy tam, gdzie przyniosą najwięcej. Typowego klienta opisuje się często jako personę.",
 x:"Naszą grupą docelową są zapracowani rodzice, więc aplikacja musi być szybka w obsłudze.",
 f:"Marketingowcy tworzą często persony, czyli krótkie wymyślone sylwetki z imieniem, wiekiem i zwyczajami, żeby nie zapominać, dla kogo pracują.",
 js:"Ludzie, dla których coś zostało przede wszystkim zrobione.",
 jl:"Kiedy firma coś robi, zastanawia się, dla kogo to jest. Książeczka z obrazkami jest dla małych dzieci, a gazeta o ogrodach dla miłośników roślin. Ci ludzie to grupa docelowa.",
 jx:"Grupą docelową naszego przedstawienia byli rodzice i dziadkowie."},
{id:"b_net_gross",cat:"biz",t:"Netto i brutto",
 s:"Brutto to kwota przed potrąceniami lub z podatkiem, netto – kwota po potrąceniach lub bez podatku.",
 l:"Wynagrodzenie brutto to kwota przed odjęciem składek na ubezpieczenia społeczne, składki zdrowotnej i zaliczki na podatek dochodowy; netto, potocznie na rękę, to to, co trafia na konto. W cenach jest odwrotnie, niż wielu się wydaje: cena netto nie zawiera VAT, a cena brutto to ta z podatkiem, którą płaci klient. W firmie zysk brutto to zysk przed opodatkowaniem, a netto – po nim. Pomylenie tych słów prowadzi do zupełnie innych oczekiwań.",
 x:"Oferta mówi o sześciu tysiącach brutto, czyli wyraźnie mniej na rękę.",
 f:"Oba słowa pochodzą z włoskiego: netto znaczy czysty, a brutto – surowy, nieoczyszczony.",
 js:"Brutto to cała kwota, a netto to to, co zostaje po odjęciu części.",
 jl:"Wyobraź sobie, że za mycie samochodów dostajesz dziesięć złotych, ale dwa złote wydajesz na płyn. Dziesięć złotych to kwota brutto. Osiem złotych, które zostają, to kwota netto.",
 jx:"Nasza lemoniadowa budka zarobiła dwadzieścia złotych brutto i piętnaście netto po zakupie cytryn."},
{id:"b_vat",cat:"biz",c:"Polska",t:"VAT (podatek od towarów i usług)",
 s:"Podatek doliczany do ceny większości towarów i usług, który firmy pobierają i odprowadzają do urzędu skarbowego.",
 l:"VAT nalicza się na każdym etapie łańcucha dostaw, ale firmy zwykle mogą odliczyć podatek zapłacony przy swoich zakupach, więc ostatecznie ponosi go głównie konsument. W Polsce podstawowa stawka wynosi dwadzieścia trzy procent, a dla części towarów i usług obowiązują stawki obniżone, osiem lub pięć procent. Mali przedsiębiorcy mogą korzystać ze zwolnienia, dopóki ich sprzedaż nie przekroczy limitu określonego w ustawie. Ceny dla konsumentów podaje się z VAT, czyli brutto.",
 x:"Na fakturze widać cenę netto, kwotę VAT i cenę brutto.",
 f:"Podatek VAT wprowadzono w Polsce piątego lipca 1993 roku, zastępując nim dawny podatek obrotowy.",
 js:"Podatek doliczany do ceny wielu rzeczy, które kupujemy.",
 jl:"Kiedy kupujesz zabawkę, część jej ceny to podatek VAT. Sklep go zbiera i oddaje państwu. Państwo wydaje te pieniądze na przykład na szkoły, drogi i szpitale.",
 jx:"Tata wytłumaczył mi, że część ceny moich nowych butów to VAT."},
{id:"b_merger",cat:"biz",t:"Fuzja i przejęcie",
 s:"Fuzja to połączenie dwóch firm w jedną, a przejęcie – kupno jednej firmy przez drugą.",
 l:"Przy fuzji dwie spółki, często podobnej wielkości, łączą się w jedną. Przy przejęciu jedna firma kupuje kontrolę nad drugą, która może zachować swoją nazwę albo zostać wchłonięta. Firmy robią to, by rosnąć, wejść na nowe rynki, zdobyć technologię lub obniżyć koszty. Duże transakcje sprawdzają urzędy antymonopolowe, w Polsce Urząd Ochrony Konkurencji i Konsumentów, które mogą je zablokować, jeśli ograniczyłyby konkurencję ze szkodą dla klientów. W żargonie mówi się o rynku M and A.",
 x:"Po fuzji dwa banki zamknęły część oddziałów stojących przy tej samej ulicy.",
 f:"Przejęcie, którego nie chce zarząd przejmowanej spółki, nazywa się wrogim przejęciem.",
 js:"Kiedy dwie firmy łączą się w jedną albo jedna kupuje drugą.",
 jl:"Czasem dwie firmy postanawiają zostać jedną dużą firmą. To fuzja. Innym razem duża firma kupuje mniejszą. To przejęcie. Trochę jak dwie drużyny, które łączą się w jedną.",
 jx:"Dwa szkolne kółka połączyły się w jedno duże kółko plastyczno-przyrodnicze."},
{id:"b_bootstrapping",cat:"biz",t:"Bootstrapping (finansowanie własne)",
 s:"Zakładanie i rozwijanie firmy za własne pieniądze i z przychodów ze sprzedaży, bez zewnętrznych inwestorów.",
 l:"Firma rozwijana metodą bootstrappingu korzysta z oszczędności założycieli i pieniędzy płaconych przez klientów, a nie z pieniędzy inwestorów czy dużych kredytów. Założyciele zachowują pełną kontrolę i muszą ostrożnie wydawać, ale rozwój bywa wolniejszy, a osobiste ryzyko finansowe większe. Tak zaczynało wiele małych firm i niektóre dziś znane przedsiębiorstwa. Przeciwieństwem jest pozyskiwanie kapitału wysokiego ryzyka, w którym inwestorzy dają pieniądze w zamian za udziały.",
 x:"Przez dwa lata rozwijali piekarnię za własne pieniądze, zanim wzięli kredyt.",
 f:"Nazwa nawiązuje do angielskiego powiedzenia o podciąganiu się za cholewki własnych butów, które pierwotnie opisywało coś niemożliwego; od tego samego obrazu pochodzi komputerowe bootowanie.",
 js:"Zakładanie firmy za własne pieniądze, bez pomocy inwestorów.",
 jl:"Bootstrapping to zakładanie małej firmy samemu, z własnych oszczędności, i powiększanie jej za pieniądze, które się zarobi. Tak jak budka z lemoniadą za kieszonkowe, a potem kupowanie cytryn za to, co się sprzedało.",
 jx:"Kuba rozkręcił sprzedaż bransoletek za pieniądze z urodzin."},
{id:"b_pl_nip",cat:"biz",only:1,c:"Polska",t:"NIP (Numer Identyfikacji Podatkowej)",
 s:"Dziesięciocyfrowy numer, który identyfikuje firmy i przedsiębiorców w rozliczeniach z urzędem skarbowym.",
 l:"NIP nadaje urząd skarbowy, a podaje się go na fakturach, w deklaracjach podatkowych i umowach. Mają go spółki, stowarzyszenia, a także osoby prowadzące działalność gospodarczą lub będące płatnikami składek. Osoby fizyczne, które nie prowadzą firmy, rozliczają się z fiskusem, posługując się numerem PESEL. Ostatnia cyfra NIP-u jest cyfrą kontrolną, obliczaną z pozostałych, co pozwala wychwycić wiele pomyłek przy wpisywaniu.",
 x:"Poproszę fakturę na firmę – zaraz podam NIP.",
 f:"Numer NIP firmy można sprawdzić w publicznych rejestrach, na przykład w wykazie podatników VAT prowadzonym przez Ministerstwo Finansów.",
 js:"Specjalny numer, który ma każda firma, żeby urząd wiedział, kto płaci podatki.",
 jl:"Każda firma w Polsce ma swój numer, tak jak ty masz imię. Ten numer to NIP. Dzięki niemu urząd wie, która firma płaci jaki podatek. Pisze się go na fakturach.",
 jx:"Mama wpisała NIP swojej firmy na fakturze dla klienta."}
]);
